Main {
    Q = A(U);
    vec4 _0 = B(U);
    vec4 _1 = C(U);
    vec4 n = B(U+vec2(0,1));
    vec4 e = B(U+vec2(1,0));
    vec4 s = B(U-vec2(0,1));
    vec4 w = B(U-vec2(1,0));
    vec4 m = 1./4.*(n+e+s+w);
    Q += (m-_0);
    float mag0 = length(_0.x);
    if (abs(_0.x)>0.)
    Q.x -= 1./6.*K*_0.x*F(mag0);
    float mag1 = sqrt(dot(_0.yz,_0.yz));
    if (length(_0.yz)>0.)
    Q.yz -= 2./6.*K*_0.yz/(Z+J*mag1);
    float mag = sqrt(dot(_0.xyz,_0.xyz)+dot(_1.xyz,_1.xyz));
    if (mag>0.)
    Q.xyz += 1./6.*K*_0.xyz*F(mag);

}

